"""Shared Markdown primitives for the baseline documents: tables, code references, escaping."""

from collections.abc import Sequence

from whisperer_contracts.jsonvalue import (
    Json,
    JsonObject,
    optional_list,
    optional_object,
    optional_str,
)

GENERATED_NOTICE = (
    "<!-- @generated by `whisperer-contracts render` from {source}; "
    "edit the JSON, not this file. -->"
)

CLASS_LEGEND = (
    "| Class | Meaning | Rule |\n"
    "|---|---|---|\n"
    "| `native` | Used by live code of a working native client (macOS 1.4.5, Windows 1.4.5), "
    "including the WhispererKit modules macOS uses "
    "| Must stay compatible: shipped clients are not updated (nfr-12) |\n"
    "| `external` | Used by an external party: acquirer, LiveKit and calendar webhooks, "
    "MCP and OAuth clients, links in emails and shared links, search engines "
    "| Must stay compatible |\n"
    "| `web` | Used only by the draft web frontend "
    "| May change together with the v2 frontend |\n"
    "| `unused` | No live consumer found | Not carried over unless D4 keeps it |\n"
    "| `excluded` | Not part of the contract: the draft's own probes and monitoring "
    "| Not checked |\n"
)


def cell(value: str) -> str:
    """Text for a table cell: without line breaks and with the pipe escaped."""
    return " ".join(value.split()).replace("|", "\\|")


def table(header: tuple[str, ...], rows: list[tuple[str, ...]]) -> list[str]:
    """A Markdown table; an empty table is replaced with an explicit `_None._` line."""
    if not rows:
        return ["_None._"]
    lines = ["| " + " | ".join(header) + " |", "|" + "---|" * len(header)]
    lines += ["| " + " | ".join(cell(item) for item in row) + " |" for row in rows]
    return lines


def reference(item: JsonObject) -> str:
    """Reference to a place in the draft code: `file:line`; dead code is marked."""
    file = optional_str(item.get("file"))
    line = item.get("line")
    place = f"`{file}:{line}`" if isinstance(line, int) and line > 0 else f"`{file}`"
    return f"{place} (dead code)" if optional_str(item.get("dead")) else place


def references(items: Sequence[Json]) -> str:
    """Comma-separated references."""
    return ", ".join(reference(optional_object(item)) for item in items) or "—"


def consumers_by_client(items: Json) -> str:
    """Consumers grouped by client: `macos (3), web (1)`."""
    counts: dict[str, int] = {}
    for raw in optional_list(items):
        client = optional_str(optional_object(raw).get("client"))
        counts[client] = counts.get(client, 0) + 1
    return ", ".join(f"{client} ({count})" for client, count in sorted(counts.items())) or "—"


def code(value: str) -> str:
    """The value as code; an empty value becomes a dash."""
    return f"`{value}`" if value else "—"
